#!/usr/bin/env bash
# Question 5: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q5_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: node-probe
  namespace: ${Q5_NS}
spec:
  selector:
    matchLabels: { app: node-probe }
  template:
    metadata:
      labels: { app: node-probe }
    spec:
      containers:
        - name: probe
          image: registry.k8s.io/pause:3.10
          resources:
            requests: { cpu: 10m, memory: 8Mi }
EOF
kubectl -n "${Q5_NS}" rollout status daemonset/node-probe --timeout=240s

case "${Q5_FAULT}" in
  kubelet-stopped) ;;
  containerd-stopped) ;;
  kubelet-binary-path) ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
